// Mapa série (recurring_config_id) -> rótulo de marca/sala.
// Edite aqui se criar novas séries no ClickMeeting.
const SERIES = {
  '17529': 'CX BR | Conheça Cxpress',
  '17497': 'CX (legado)',
  '17544': 'BUZZ LATAM | Atención',
  '17560': 'CREATORS case',
  '17601': 'BUZZ BR | MCP'
};

// Junta as conferências das duas chamadas (ativas + inativas).
// Tolera tanto resposta já dividida em itens quanto array bruto num item.
const confs = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j)) confs.push(...j);
  else if (j && Array.isArray(j.data)) confs.push(...j.data);
  else if (j && (j.id || j.recurring_config_id)) confs.push(j);
}

const out = [];
for (const c of confs) {
  const rid = String(c.recurring_config_id == null ? '' : c.recurring_config_id);
  if (!SERIES[rid]) continue; // ignora séries que não nos interessam
  out.push({ json: { sessionId: c.id, recurringConfigId: rid, marca: SERIES[rid] } });
}
return out;

// Deriva a série/marca de cada inscrito pelo room_pin do PRÓPRIO link de acesso,
// cruzando com o room_pin das conferências. Robusto — NÃO depende de pairedItem
// (o pairedItem após o split do array do HTTP é instável e jogava todos na 1ª sessão).
const SERIES = {
  '17529': 'CX BR | Conheça Cxpress',
  '17497': 'CX (legado)',
  '17544': 'BUZZ LATAM | Atención',
  '17560': 'CREATORS case',
  '17601': 'BUZZ BR | MCP'
};

// Mapa room_pin -> recurring_config_id, montado a partir das conferências.
const pinToSerie = {};
for (const nodeName of ['CM: conferências ativas', 'CM: conferências inativas']) {
  let items = [];
  try { items = $(nodeName).all(); } catch (e) { items = []; }
  for (const it of items) {
    const arr = Array.isArray(it.json) ? it.json : [it.json];
    for (const c of arr) {
      if (c && c.room_pin != null) {
        pinToSerie[String(c.room_pin)] = String(c.recurring_config_id == null ? '' : c.recurring_config_id);
      }
    }
  }
}

function serieFromUrl(url) {
  const m = String(url || '').match(/clickmeeting\.com\/(\d+)/);
  return m ? (pinToSerie[m[1]] || '') : '';
}

const rows = [];
for (const item of $input.all()) {
  const j = item.json || {};
  let recs = [];
  if (Array.isArray(j)) recs = j;
  else if (Array.isArray(j.body)) recs = j.body;
  else if (j.email || j.visitor_nickname || j.id) recs = [j];

  for (const r of recs) {
    const f = (r && r.fields) || {};
    const geo = (r && r.geo) || {};
    const email = (r.email || f['Email Address'] || '').toString().toLowerCase();
    if (!email) continue;
    const rid = serieFromUrl(r.url);
    rows.push({ json: {
      'Data inscrição': r.registration_date || r.registration_confirmed || '',
      'Nome': r.visitor_nickname || f['Name'] || '',
      'Email': email,
      'Empresa': f['Company'] || '',
      'País': geo.country || '',
      'Cidade': geo.city || '',
      'Marca/Sala': SERIES[rid] || '(desconhecida)',
      'Série': rid,
      'Sessão': r.session_id || '',
      'Origem': r.http_referer || '',
      'Link de acesso': r.url || ''
    }});
  }
}
return rows;
